			f.native.Entities = append(f.native.Entities, nativeEntity{Path: "Assets/Fixture/Cart.prefab", GUID: sourceGUID, FileID: i64(otherID), TypeName: "UnityEngine.Transform"})
			bad := f.native.References[0]
