	meta := "Assets/ThirdParty/VendorShim.asmdef.meta"
	metaBytes := []byte("fileFormatVersion: 2\nguid: 55555555555555555555555555555555\n")
	writeFile(t, f.opts.Root, f.opts.Project+"/"+meta, metaBytes)
	f.receipt.ContextInventory.AssetsCode = append(f.receipt.ContextInventory.AssetsCode, fileHash{link, digest(linkBytes)}, fileHash{meta, digest(metaBytes)})
	slices.SortFunc(f.receipt.ContextInventory.AssetsCode, func(a, b fileHash) int { return strings.Compare(a.Path, b.Path) })
